SELECT oh.ORDER_NO AS \"ORDER NUMBER\",      oh.STATUS AS \"STATUS\",      oh.SUPPLIER AS \"SUPPLIER\",      s.SUP_NAME AS \"SUPPLIER NAME\",     oh.LOCATION AS \"LOCATION\",      oh.DEPT AS \"DEPARTMENT\",      d.DEPT_NAME AS \"DEPARTMENT NAME\",      ol.ITEM AS \"ITEM\",      im.ITEM_DESC AS \"ITEM DESCRIPTION\",     ol.QTY_ORDERED AS \"QUANTITY ORDERED\",      isc.TI AS \"TI\",      isc.HI AS \"HI\",      (isc.TI * isc.HI * ol.QTY_ORDERED) AS \"TOTAL VOLUME UNITS\" FROM MFCS_RDS.RDS_WV_ORDHEAD oh     JOIN MFCS_RDS.RDS_WV_ORDLOC ol ON oh.ORDER_NO = ol.ORDER_NO     JOIN MFCS_RDS.RDS_WV_ITEM_MASTER im ON ol.ITEM = im.ITEM     JOIN MFCS_RDS.RDS_WV_SUPS s ON oh.SUPPLIER = s.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_DEPS d ON oh.DEPT = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc ON ol.ITEM = isc.ITEM AND oh.SUPPLIER = isc.SUPPLIER WHERE oh.STATUS IN ('A','W') ORDER BY oh.ORDER_NO, ol.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>ORDER NUMBER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER NAME</ds:name><ds:datatype>varchar(240)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPARTMENT</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPARTMENT NAME</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>ITEM</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM DESCRIPTION</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:co